<?php if(!empty($personTypes)): ?><nav class="pillbar" aria-label="نوع رسانه پرونده"><a class="pill <?= empty($selectedType)?'active':'' ?>" href="<?= e(url('profile',['id'=>$profileId])) ?>">همه رسانه‌ها</a><?php foreach($personTypes as $type): ?><a class="pill <?= (int)($selectedType??0)===(int)$type['id']?'active':'' ?>" href="<?= e(url('profile',['id'=>$profileId,'media_type'=>$type['id']])) ?>"><?= e($type['title']) ?> · <?= fa($type['total']) ?></a><?php endforeach ?></nav><?php endif ?><?php view('cards',['images'=>$images]); ?>
